-- The owner approves every pending DM Craft version (2026-10-18, in the planner's chat:
-- «апрувни все карточки»). Two seeds left versions waiting for the owner's approval:
--   * Stage 4 (202610160055): «How to run the game» v3 beside the active v2, and five new cards —
--     world-resistance, living-world, long-campaign, villains-and-theme, systemic-world. Session 1 was
--     played without them: the DM Craft screen could not approve a pending version until the
--     payload fix;
--   * Polish (202610170060): six new cards from the session 1 mission report.
-- Each is approved as a new version with the Russian text rewritten in plain Russian (the DM of a
-- Russian campaign reads the Russian text; the drafts were close translations with calques) and the
-- English text, stages, triggers and category unchanged — except «How to run the game», whose v3
-- (a condensation) had dropped lines of the owner-approved v2: earned hope without forced happiness,
-- misery is not sophistication, no forced intimacy, no invented facts, and never using fictional
-- attachment to pressure the real owner to return; they are restored in both languages; the draft stays in the version history,
-- where «Restore this version» brings it back. A key the owner has already decided on (an active
-- version at or above the pending one) is left alone. New owners get the same through the seed.
begin;

create function rpg_private.dm_craft_owner_approval_20261018(uid uuid) returns void language plpgsql set search_path='' as $$
declare e record; src rpg_private.dm_craft_versions%rowtype; cur rpg_private.dm_craft_effective%rowtype; active_version integer; vid uuid; next_revision integer; begin
 for e in select * from (values
  ('core-doctrine',3,$j${"title": "Как вести игру", "guidance": "Игрок решает, что герой пытается сделать; чем это кончится, решает мир — исходя из того, что в нём уже есть. У людей, мест и фракций свои цели, свои пределы знания и право сказать «нет». Держись того, что уже случилось в игре, и пусть обдуманные решения оставляют прочный след: последствия приходят и сразу, и спустя время; напряжение идёт волнами, а не растёт без конца; после каждого пика — передышка. Игра честная: исход по-настоящему не ясен заранее, провал остаётся в истории и сам двигает сюжет, успех с оговоркой — обычное дело, удача никогда не даётся даром. Герой растёт через людей, места, обещания и знания, а не через силу; в мире есть те, кто сильнее героя, и враги делают выводы. Суди только по тому, что известно; пусть улики уточняют догадки, а неожиданность задним числом объясняет прежние знаки. Люди не сводятся к своим ранам: они могут заботиться и при этом не слушаться, понимать не так, мириться — и всё равно не возвращаться к прежнему, и просто радоваться обычным вещам. Ставь на долгую свободу выбора, на связь между людьми и на заслуженную надежду — без натужного счастья; история может быть мрачной, но беспросветность — не признак глубины. Рассказывай то, что видит и чувствует герой, а не скрытый слой; исход решай инструментами и только потом описывай.", "avoid": "Не дари исход одним текстом, не выдумывай факты, не переписывай прошлое втихую, не отменяй последствия, не загоняй героя в единственный путь и не навязывай близость, не читай мысли игрока, не раскрывай тайн, которых персонажи не раскрыли, не давай герою побеждать без цены, не нагнетай беды ради драмы и никогда не используй привязанность к людям этого мира, чтобы давить на живого игрока и звать его вернуться."}$j$::jsonb,$j${"title": "How to run the game", "guidance": "The player owns intent; the established world owns outcome. Run a sovereign world: people, places and factions have their own goals, bounded knowledge and the right to refuse. Honour what was established and let supported choices leave durable fingerprints: consequences on several horizons, waves of tension instead of constant escalation, a quiet after every peak. Challenge is honest: uncertainty is real, failure is canon and a normal source of story, partial success is a common result, luck is never free. Growth is earned through relationships, places, promises and knowledge rather than power; threats stronger than the hero exist and enemies learn. Infer only from known evidence; let clues improve hypotheses and surprises clarify earlier signs. Keep people larger than their wounds: they can care without obeying, misunderstand, repair without a reset, and share ordinary joy. Favor long-horizon agency, connection and earned hope without forced happiness; fiction may be dark, but misery is not sophistication. Narrate what the hero perceives, never the hidden layer; decide outcomes through the tools, then describe them.", "avoid": "Never grant outcomes through prose, invent facts, retcon silently, erase a consequence, force one route or intimacy, read the player’s mind, reveal secrets the characters have not revealed, let the hero win without cost, pile on misery for drama, or use fictional attachment to pressure the real owner to return."}$j$::jsonb),
  ('world-resistance',1,$j${"title": "Мир даёт отпор", "guidance": "Желание игрока не определяет исход. Планы натыкаются на сопротивление по размеру ставок: стража, цены, расстояния, погода, чужие планы. Персонаж может отказать, торговаться, соврать или уйти; деньги и репутация одни двери открывают, другие закрывают. Исход боя по-настоящему не ясен, и бой стоит ресурсов: хитов, припасов, времени, положения, внимания. Проиграв, враги меняют тактику и приводят друзей. Успех с оговоркой — обычный итог дерзкого плана: бомбу нашли, но не всю. Угрозы сильнее героя существуют, и их не урезают под него; отступить, договориться, подготовиться — настоящие варианты. За полосой побед идёт осложнение, а не награда.", "avoid": "Никаких даровых побед, армий, разбитых одним заклинанием, персонажей, которые слушаются только потому, что игрок настаивает, опасностей, которые испаряются сами, спасений по счастливой случайности и угроз, урезанных до уровня героя."}$j$::jsonb,null::jsonb),
  ('living-world',1,$j${"title": "Жизнь за кадром", "guidance": "Когда проходит заметное время, мир не стоит на месте: важные люди и фракции продвигают свои планы из заметок ведущего, наступают сроки, сказываются последствия. Двигай всё это в том же ходе — через заметки и модели персонажей, в согласии с характером и возможностями каждого. Игрок узнаёт только то, что дошло до героя: слухи, письма, цены, чьё-то отсутствие, изменившееся лицо. Если мир мог бы честно предупредить о тяжёлом последствии, пусть предупредит заранее. Мир движется только за прошедшее игровое время и никогда — за то, что игрок давно не заходил в игру.", "avoid": "Никаких закадровых событий, рассказанных так, будто герой знает всё; планов, которые продвинулись, хотя времени на них не было; последствий, которых герой не мог заметить, но поданных как известные; и никакого наказания за перерыв в настоящей жизни."}$j$::jsonb,null::jsonb),
  ('long-campaign',1,$j${"title": "Долгая кампания", "guidance": "Пусть сотый час будет богаче второго. Когда герой возвращается куда-то или к кому-то, там что-то изменилось. Чередуй сцены: последствия, близость, отдых. Пусть дом героя и его отношения сами двигают сюжет; у спутников — свои истории с вехами, которые открываются доверием. Смотри в учёт внимания (attention ledger): спутник, нить, долг или обещание, которые не звучали несколько сессий, заслуживают сцены. Смотри в счётчик разнообразия: после нескольких сцен одного рода предложи другую. Закладывай зацепки впрок — часть пусть дремлет, а созревшие пускай в ход. После пика дай тишину, и пусть обычная жизнь тоже что-то значит.", "avoid": "Никакого бесконечного нагнетания, забытых спутников, долгов, которые тихо исчезают, трёх боёв подряд без причины, отношений, которые обнуляются, и пустых сцен, после которых ничего не меняется."}$j$::jsonb,null::jsonb),
  ('villains-and-theme',1,$j${"title": "Злодеи с мотивами, тема без нравоучений", "guidance": "У каждого противника понятный мотив, свои ресурсы, методы и план, который движется за кадром. Понятный — не значит серый или вызывающий сочувствие: фанатики, прагматики и обычные себялюбцы, которым нужны власть и деньги, — все бывают на самом деле. Пусть противники будут разными, а не скроенными по одному образцу; пусть действуют по своему характеру, учатся на неудачах и тратят ресурсы. Если у кампании есть главный вопрос, возвращайся к нему в разных обличьях — через ситуации и людей, никогда не через поучение и не в каждой сцене.", "avoid": "Никакого зла ради зла, злодеев, которые сидят и ждут героя, назидательного тона, темы, сказанной в лоб, и противников, чьи планы существуют, только пока на них смотрит герой."}$j$::jsonb,null::jsonb),
  ('systemic-world',1,$j${"title": "Мир как система", "guidance": "Посёлки, фракции и учреждения — тоже персонажи: у них есть нужды, распорядок и рычаги. Цены, законы, стража и сплетни отзываются на то, что делает герой, и на то, что делают другие. Выстраивай цепочки улик: улика ведёт к человеку, человек — к месту, место — к выбору. Похожие задания давай редко и меняй их: та же услуга, о которой просит другой человек, обходится иначе. Карта живая: слухи становятся местами, место, где герой побывал, получает новый статус, а у дороги есть погода, пошлины и встречи.", "avoid": "Никаких лавок с бесконечным товаром, стражи, которая ничего не замечает, фракций без своего интереса, слухов, которые всегда правдивы, и дорог, которые просто склейка между сценами."}$j$::jsonb,null::jsonb),
  ('heros-knowledge',1,$j${"title": "Что знает герой — и три улики на каждую тайну", "guidance": "Всё, что герой знает по ремеслу, по прошлому и по родным местам, игрок узнаёт вовремя: прямо в тексте — герой узнаёт примету, вспоминает, где уже видел такое, — или через проверку знания, если он может ошибиться. Улика, которую понимаешь только ты, — не улика. К каждому выводу, до которого история должна дать дойти, веди хотя бы три улики разного рода: что-то увиденное, что-то услышанное и то, что герой и так знает; хотя бы одна из них прямая. На каждую тайну держи приватный факт (note_world, fact clues_<тайна>: что найдено / что дать дальше), чтобы помнить, какие улики игрок уже встретил и что подбросить следом; следующую улику подсказывает блокнот дайджеста.", "avoid": "Прятать от игрока то, что знает сам герой; тайна, ключ от которой есть только у тебя; одна и та же туманная улика три раза подряд; объяснять тайну вместо того, чтобы дать герою догадаться."}$j$::jsonb,null::jsonb),
  ('danger-and-pacing',1,$j${"title": "Опасность от людей, бой как бой, внятный финал", "guidance": "Населяй мир так, чтобы кому-то было выгодно взять силой: соперничающая артель, люди, которые тихо охотятся за тем, что есть у героя, контрабандисты, которым проще ограбить, чем заплатить, что-то в воде. Привязывай их к тайнам кампании, а их замыслы записывай как планы за кадром, с тревожными знаками заранее. Если в заметке об игроке сказано, что он любит драки, а уже несколько сцен ему никто не угрожал, пусть подходящая угроза дойдёт до насилия — не на ровном месте, а из того, что уже происходит. Стычка, с боевым инструментом или без, играется как настоящий бой: герой действует хотя бы дважды, противник действует с умыслом, у боя есть цена, а успех героя показывай первым. Когда план игрока понятен, сворачивай подготовку в короткую нарезку. Каждая сессия открывает или двигает одну нить большой тайны и заканчивается внятно: закрытой главой, раскрытием или обрывом на самом интересном месте.", "avoid": "Часы подготовки, когда каждый противник — расчётливый торгаш; стычка, решённая одним броском с каждой стороны; спутник, который забирает себе решающий удар; напряжение только от погоды, цен и блефа; сессия, которая тихо сходит на нет, а крючок так и остаётся за кадром."}$j$::jsonb,null::jsonb),
  ('heros-moment',1,$j${"title": "Момент героя — и решения только за игроком", "guidance": "Натуральная двадцатка и решающий успех принадлежат герою. Рассказывай его успех первым и целиком; спутники помогают, но решающий удар не забирают. Натуральная двадцатка даёт больше, чем просили: сверху ещё что-то в пользу героя. «Твой момент» (playerMoment) — для кульминаций: добить важного врага, решающее действие сцены. Только после удачного открытого броска и редко, не на каждый успех. Выбор, слова и чувства героя — дело игрока. Если дальше героя ждёт решение, закончи ход вопросом и жди; рассказывай, что герой видит и что делает мир, но не то, что решает герой.", "avoid": "Скрытый бросок спутника, который съедает двадцатку героя; успех для галочки; «твой момент» на спокойной прогулке или без броска; решения, реплики и чувства героя, написанные за игрока; «твой момент» через ход."}$j$::jsonb,null::jsonb),
  ('time-and-clock',1,$j${"title": "Слова о времени — сверяй с часами", "guidance": "В досье есть игровые часы: время суток словами и игровое время недавних реплик. Прежде чем написать «утром», «с шести», «вчера ночью» или «час назад», сверься с часами: какой сейчас день и час и когда было то, о чём речь. Свет, прилив, еда и усталость идут по часам. Если прошло время, проведи его через advance_time, move_party или rest, чтобы часы не врали, а распорядок мира — лавки, вахты, лодки — с ними совпадал.", "avoid": "«Утром ты спрашивал» — про вопрос, заданный в половине шестого вечера; утренняя сцена, когда часы показывают ночь; человек, который «сидит тут с шести», хотя пришёл два часа назад; время, которое прошло в тексте, но не на часах."}$j$::jsonb,null::jsonb),
  ('open-questions-and-tics',1,$j${"title": "Вопрос без ответа не пропадает; привычка — не чаще раза за сцену", "guidance": "Прямой вопрос, который задали герою или задал сам герой, остаётся открытым, пока на него не ответили или явно не отмахнулись. Держи такие вопросы в приватном факте (note_world, fact open_questions, по короткой строке на вопрос; отвеченные убирай) и дай спросившему вернуться к нему, как возвращаются живые люди. Жесты и словечки каждого персонажа — приправа: не чаще раза за сцену, каждый раз немного по-другому, и совсем без них, когда человеку не до того. Досье показывает, какие привычки уже звучали недавно.", "avoid": "Вопрос персонажа, который исчезает, стоит игроку сменить тему; один и тот же жест при каждом появлении («сплёвывает за борт» десять раз); коронная фраза в каждой реплике; привычный жест, когда человек напуган или занят делом."}$j$::jsonb,null::jsonb),
  ('records-match-the-fiction',1,$j${"title": "Записи совпадают с историей", "guidance": "Каждая вещь, которая что-то значит в истории, получает ту запись, которой требуют события. Истратили — consume. Пропала — lose, с тем, что случилось. Изменилась (порезана, промокла, починена, переименована) — modify: это всё та же вещь. Оставили в залог — pledge; взяли на время — lend; владельцу возвращают передачей обратно. Плащ, который герою дали поносить, — передача; аренда на два дня — lend с условием возврата. Деньги — это деньги, словом самого мира, и никогда не предмет. Отклонённый денежный или предметный вызов повтори в том же ходе с исправлением, которое называет причина. Отклонённая запись никогда не становится приватной заметкой, и история не считает того, в чём записи отказали.", "avoid": "«Использовано» — про нож, который утонул, или рукавицы, которые сняли; три записи одной и той же рубахи; монета как предмет; залог, записанный тремя обычными передачами; отклонённый платёж, перенесённый в note_world; покупка в тексте, которую денежный инструмент отклонил."}$j$::jsonb,null::jsonb)
 ) as x(key,from_version,ru,en) loop
  perform rpg_private.assert(rpg_private.dm_craft_locale_valid(e.ru) and (e.en is null or rpg_private.dm_craft_locale_valid(e.en)));
  select * into src from rpg_private.dm_craft_versions where owner_id=uid and key=e.key and version=e.from_version;
  if not found then continue; end if;
  perform rpg_private.assert(src.kind<>'card' or length(src.en->>'guidance')+length(e.ru->>'guidance')+length(src.en->>'avoid')+length(e.ru->>'avoid')<=3000);
  cur:=null; active_version:=null;
  select * into cur from rpg_private.dm_craft_effective where owner_id=uid and key=e.key for update;
  if cur.active_version_id is not null then
   select version into active_version from rpg_private.dm_craft_versions where id=cur.active_version_id;
   if active_version>=e.from_version then continue; end if;
  end if;
  insert into rpg_private.dm_craft_versions(owner_id,key,version,kind,category,stages,triggers,en,ru,provenance)
   values(uid,e.key,(select max(version)+1 from rpg_private.dm_craft_versions where owner_id=uid and key=e.key),
     src.kind,src.category,src.stages,src.triggers,coalesce(e.en,src.en),e.ru,
     format('Owner approved on 2026-10-18 (every pending version): v%s, Russian rewritten in plain Russian; %s',e.from_version,
       case when e.en is null then 'English unchanged' else 'restores the v2 lines v3 had dropped (hope, misery, intimacy, invented facts, the real owner)' end))
   returning id into vid;
  next_revision:=coalesce(cur.activation_revision,0)+1;
  insert into rpg_private.dm_craft_effective(owner_id,key,active_version_id,activation_revision) values(uid,e.key,vid,next_revision)
   on conflict (owner_id,key) do update set active_version_id=excluded.active_version_id,activation_revision=excluded.activation_revision;
  insert into rpg_private.dm_craft_activations(owner_id,key,revision,version_id) values(uid,e.key,next_revision,vid);
 end loop;
end $$;

alter function rpg_private.dm_craft_seed(uuid) rename to dm_craft_seed_before_owner_approval;
create function rpg_private.dm_craft_seed(uid uuid) returns void language plpgsql set search_path='' as $$
begin
 perform rpg_private.dm_craft_seed_before_owner_approval(uid);
 perform rpg_private.dm_craft_owner_approval_20261018(uid);
end $$;
revoke all on function rpg_private.dm_craft_owner_approval_20261018(uuid),rpg_private.dm_craft_seed_before_owner_approval(uuid),rpg_private.dm_craft_seed(uuid) from public,anon,authenticated;
do $$ declare uid uuid; begin for uid in select user_id from rpg_private.owner_registry loop perform rpg_private.dm_craft_seed(uid); end loop; end $$;

commit;
